export type BetaTunnelCertificatesPageCursor = PageCursor<BetaTunnelCertificate>;

/**
 * A CA certificate attached to a tunnel.
 */
export interface BetaTunnelCertificate {
  /**
   * Unique identifier for the certificate, prefixed with `tcrt_`.
   */
  id: string;

  /**
   * RFC 3339 datetime string indicating when the certificate was archived. Null if
   * it is still in the trusted set.
   */
  archived_at: string | null;

  /**
   * RFC 3339 datetime string indicating when the certificate was registered.
   */
  created_at: string;

  /**
   * RFC 3339 datetime string indicating when the certificate expires, or `null` if
   * it does not expire.
   */
  expires_at: string | null;

  /**
   * Lowercase hex SHA-256 fingerprint of the certificate's DER encoding.
   */
  fingerprint: string;

  /**
   * ID of the tunnel the certificate is registered against.
   */
  tunnel_id: string;

  type: 'tunnel_certificate';
}

export interface CertificateCreateParams {
  /**
   * Body param: PEM-encoded X.509 CA certificate. Must contain exactly one
   * certificate and no private-key material. Maximum 8KB.
   */
  ca_certificate_pem: string;

  /**
   * Header param: This endpoint is in beta: requests must send
   * `mcp-tunnels-2026-06-22` in this header.
   */
  betas?: Array<BetaAPI.AnthropicBeta>;

  /**
   * Header param: Optional header to select the Workspace for this request. The
   * value is a Workspace ID (for example, `wrkspc_011CZkZaBF1tNoB5wlCeusgy`).
   *
   * Only needed for credentials that can act on more than one Workspace. A
   * credential that belongs to a specific Workspace may omit it; if sent, it must
   * match that Workspace.
   */
  workspace_id?: string;
}

